from itertools import product
from typing import Callable, Dict, List, Optional, Tuple

Compress = Callable[[int, int], int]

def merkle_damgard(f: Compress, iv: int, msg: List[int]) -> int:
    s = iv
    for b in msg:
        s = f(s, b)
    return s

def find_md_collision(f: Compress, iv: int, blocks: List[int],
                      length: int) -> Optional[Tuple[List[int], List[int]]]:
    seen: Dict[int, List[int]] = {}
    for combo in product(blocks, repeat=length):
        msg = list(combo)
        d = merkle_damgard(f, iv, msg)
        if d in seen and seen[d] != msg:
            return seen[d], msg
        seen[d] = msg
    return None

def extract_compress_collision(f: Compress, iv: int, m1: List[int], m2: List[int]):
    s1 = s2 = iv
    for b1, b2 in zip(m1, m2):
        o1, o2 = f(s1, b1), f(s2, b2)
        if (s1, b1) != (s2, b2) and o1 == o2:
            return (s1, b1), (s2, b2)
        s1, s2 = o1, o2
    return None

if __name__ == "__main__":
    weak: Compress = lambda a, b: (a + b) % 4
    col = find_md_collision(weak, 0, [0, 1, 2, 3], 2)
    print("MD collision:", col)
    if col:
        print("compression collision:", extract_compress_collision(weak, 0, *col))

from itertools import product
from typing import Callable, Dict, List, Tuple

Compress = Callable[[int, int], int]

def merkle_damgard(f: Compress, iv: int, msg: List[int]) -> int:
    s = iv
    for b in msg:
        s = f(s, b)
    return s

def md_end(f: Compress, msg: List[int]) -> Callable[[int], int]:
    return lambda a: merkle_damgard(f, a, msg)

def anti_hom(f: Compress, m1: List[int], m2: List[int],
             probe: List[int]) -> bool:
    lhs = md_end(f, m1 + m2)
    rhs = lambda a: md_end(f, m2)(md_end(f, m1)(a))   # reversed composition
    return all(lhs(a) == rhs(a) for a in probe)

def faithful(f: Compress, blocks: List[int], length: int,
             probe: List[int]) -> bool:
    seen: Dict[Tuple[int, ...], List[int]] = {}
    for combo in product(blocks, repeat=length):
        msg = list(combo)
        key = tuple(md_end(f, msg)(a) for a in probe)
        if key in seen and seen[key] != msg:
            return False
        seen[key] = msg
    return True

if __name__ == "__main__":
    n = 3
    f: Compress = lambda a, b: a * n + b      # pair-injective embedding
    probe = list(range(10))
    print("anti-homomorphism holds:", anti_hom(f, [1, 2], [0, 2], probe))
    print("faithful on length 3   :", faithful(f, list(range(n)), 3, probe))

